-- Adds Kevin Murphy +CODE and +GLOSS to the brand marquee on the login
-- page. These are not trainable catalog entries (no steps, not something a
-- customer selects when requesting access) — hero_visible is left false so
-- they also don't show as a floating logo on the hero photo itself, just
-- in the rotating marquee strip like every other brand with a logo.

insert into brands (name, logo_url, hero_visible)
values
  ('Kevin Murphy +CODE', 'data:image/png;base64,', false),
  ('Kevin Murphy +GLOSS', 'data:image/png;base64,', false)
on conflict do nothing;
